import click
from click.testing import CliRunner


class Foo:
    pass


class Bar:
    pass


def test_flag_value_class_default_not_instantiated():
    seen = []

    @click.command()
    @click.option("--foo", "ty", flag_value=Foo, type=click.UNPROCESSED, default=True)
    @click.option("--bar", "ty", flag_value=Bar, type=click.UNPROCESSED)
    def main(ty):
        seen.append(ty)

    result = CliRunner().invoke(main, [])
    assert result.exit_code == 0, result.output
    assert seen == [Foo]

import click


class StrictVersion:
    """Mimics semver.Version: __eq__ parses string operands and raises on invalid ones."""

    def __init__(self, s):
        self.s = s

    def __str__(self):
        return self.s

    def __eq__(self, other):
        if isinstance(other, str):
            parts = other.split(".")
            if len(parts) != 3 or not all(p.isdigit() for p in parts):
                raise ValueError(f"{other!r} is not valid SemVer string")
            return self.s == other
        return NotImplemented

    __hash__ = None


def test_help_with_object_default_whose_eq_raises_on_str():
    @click.command()
    @click.option("--version", default=StrictVersion("1.0.0"), show_default=True)
    def cli(version):
        pass

    ctx = click.Context(cli)
    help_text = cli.get_help(ctx)
    assert "1.0.0" in help_text

import click
from click.testing import CliRunner


def test_usage_error_hint_skips_shadowed_help_option():
    @click.group(context_settings={"help_option_names": ["-h", "--help"]})
    def cli():
        pass

    @click.command()
    @click.argument("required_arg")
    @click.option("--host", "-h", "host", default="localhost")
    def foo(required_arg, host):
        click.echo(f"required_arg={required_arg} host={host}")

    cli.add_command(foo)

    result = CliRunner().invoke(cli, ["foo"])

    assert result.exit_code == 2
    assert "Missing argument 'REQUIRED_ARG'" in result.output
    # The hint must suggest a help option that actually works for `foo`.
    assert "foo --help' for help." in result.output
    assert "foo -h' for help." not in result.output

import pytest
import click
from click.testing import CliRunner


@click.command()
@click.option("--without-xyz", "enable_xyz", flag_value=False)
@click.option("--with-xyz", "enable_xyz", flag_value=True, default=True)
def foo(enable_xyz):
    click.echo(f"enable_xyz = {enable_xyz}")


@pytest.mark.parametrize(
    ("args", "expected"),
    [
        ([], "enable_xyz = False"),
        (["--with-xyz"], "enable_xyz = True"),
        (["--without-xyz"], "enable_xyz = False"),
        (["--with-xyz", "--without-xyz"], "enable_xyz = False"),
        (["--without-xyz", "--with-xyz"], "enable_xyz = True"),
    ],
    ids=["no-flags", "with-xyz", "without-xyz", "with-then-without", "without-then-with"],
)
def test_shared_dest_bool_flag_pair(args, expected):
    result = CliRunner().invoke(foo, args)
    assert result.exit_code == 0, result.output
    assert result.output.strip() == expected

import click
from click.testing import CliRunner


@click.command()
def cmd_confirm():
    click.confirm(click.style("Hello World!", fg="green"), abort=True)


def test_confirm_strips_ansi_with_color_false():
    runner = CliRunner()
    result = runner.invoke(cmd_confirm, input="Y", color=False)
    assert result.output == "Hello World! [y/N]: Y\n"

import click

import click._termui_impl


def test_progressbar_show_pos_full_completion_with_update_min_steps(runner, monkeypatch):
    @click.command()
    def cli():
        with click.progressbar(
            range(20),
            show_pos=True,
            update_min_steps=7,
        ) as bar:
            for _ in bar:
                pass

    monkeypatch.setattr(click._termui_impl, "isatty", lambda _: True)
    output = runner.invoke(cli, []).output

    lines = [line for line in output.split("\r") if "[" in line]
    assert "20/20" in lines[-1]
